import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on effect size
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        # Use the actual effect size from feats.types
        effect_size = feats.types[i]
        # Ensure effect_size is numeric
        try:
            eff_val = float(effect_size)
            if abs(eff_val) > 0.2:  # Strong effect size threshold
                # Approximate t-statistic from effect size and sample size
                t_stat = eff_val * np.sqrt(feats.n - 2)
                if abs(t_stat) > 2.5:  # Significant t-test threshold
                    strong_candidates.append((fid, abs(eff_val)))
        except (ValueError, TypeError):
            continue

    # Sort by effect size
    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    filtered_candidates = []
    excluded = set()
    for fid, _ in strong_candidates:
        if fid in excluded:
            continue
        filtered_candidates.append(fid)
        # Mark correlated features for exclusion
        for other_fid in feats.ids:
            if other_fid != fid and other_fid not in excluded:
                try:
                    col_a = feats.column(fid)
                    col_b = feats.column(other_fid)
                    if col_a < len(feats.x[0]) and col_b < len(feats.x[0]):
                        corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]
                        if abs(corr) > 0.6:
                            excluded.add(other_fid)
                except (KeyError, IndexError):
                    continue

    # Select top drivers
    drivers = tuple(filtered_candidates[:MAX_DRIVERS])

    # For logistic regression, include all relevant features
    columns = tuple(filtered_candidates)

    # Check for interaction terms (products)
    products = []
    for i, a in enumerate(columns):
        for b in columns[i+1:]:
            # Check if interaction term would be meaningful
            try:
                col_a = feats.column(a)
                col_b = feats.column(b)
                if col_a < len(feats.x[0]) and col_b < len(feats.x[0]):
                    corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]
                    if abs(corr) > 0.3:
                        products.append((a, b))
            except (KeyError, IndexError):
                continue

    # Create weighted score using top features
    loadings = {}
    for i, fid in enumerate(columns[:5]):  # Top 5 features for loading
        loadings[fid] = 1.0 / (i + 1)  # Inverse ranking weights

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

